-- ============================================================================
-- Migration 1048: Conveyor Conversion Coating machines (the pretreatment washers), USA
-- ============================================================================
-- Conveyor Conversion Coating was the one surface treatment with no machine: memory/SurfaceTreatment/Machine has no
-- file for it, so migration 820 seeded none and the process was "not costed" on every part.
--
-- The machines are in the country exports (memory/Countries data, commodity Surface Treatment, machine type Conveyor
-- Conversion Coating): 16 washers, 3 to 12 stages, with their stage lengths, opening, price and power, the same in
-- every country file (checked against a second one). Those files carry each country's overhead rates and none for the
-- USA, so the rows are seeded with no machine hour rate: the HR Rates engine prices a machine that has none from its
-- price and its power, the rate the HR Rates screens show for it. A washer's cost is mostly the energy of its pumps
-- and heaters, so each row carries its rated power as its draw and the USA industrial electricity price the
-- application already holds (location_electricity_prices: 0.0851 USD/kWh, U.S. EIA Electric Power Monthly Table 5.3,
-- 2025 average), read from that table here; without them the engine would price the machine with no energy at all.
-- Labour: the USA rate of the process's wage grade (2 - Metal, 29.95 USD/hr), the value every Surface Treatment
-- machine of that grade carries (migration 820); the washers are not crewed (0 operators).
--
-- Idempotent: a (machine_class, location, machine_name) already present is skipped, as in migration 820.
-- Verify: SELECT count(*) FROM mhr_records WHERE machine_class = 'surface_conveyor_conversion_coating' AND location = 'USA';  -- 16
-- ============================================================================

INSERT INTO mhr_records (
  machine_class, location, machine_name, currency_code, country_code, source_type, process_group, operators, setup_time_hr, landed_machine_cost,
  usd_labor_rate_per_hr, benchmark_labor_rate_usd_hr, usd_lhr_total, work_center_labor_rate_factor, labor_time_standard, wage_grade, machine_price_usd,
  machine_width_mm, footprint_allowance_factor, machine_power_kw, machine_life_yr, installation_factor_pct, machine_uptime_pct,
  annual_maintenance_factor_pct, salvage_value_factor_pct, supplies_cost_per_year, avg_utilization, good_part_yield, manufacturer_country,
  max_y_mm, max_z_mm, capability_source, specs, benchmark_source_key, power_kwh_per_hour, electricity_cost_per_kwh
)
SELECT 'surface_conveyor_conversion_coating', 'USA', v.machine_name, 'USD', 'US', 'BENCHMARK', 'Surface Treatment', v.operators, v.setup_time_hr, v.price,
  29.95, 29.95, 29.95, 1, 1, '2 - Metal', v.price,
  v.width_mm, v.footprint, v.power_kw, v.life_yr, v.installation_pct, v.uptime_pct,
